"""Blender-only worker; its settings file is generated by the trusted adapter."""
import json
from pathlib import Path
import sys
import bpy
import bmesh

settings=json.loads(Path(sys.argv[sys.argv.index('--')+1]).read_text())
if bpy.app.version<(3,4,0):raise RuntimeError('Blender 3.4 or newer is required.')
bpy.ops.wm.read_factory_settings(use_empty=True)
if hasattr(bpy.ops.wm,'obj_import'):
    bpy.ops.wm.obj_import(filepath=settings['input'],forward_axis='NEGATIVE_Z',up_axis='Y')
else:
    bpy.ops.import_scene.obj(filepath=settings['input'],axis_forward='-Z',axis_up='Y',use_image_search=False)
objects=[o for o in bpy.context.scene.objects if o.type=='MESH']
if not objects:raise RuntimeError('OBJ importer created no mesh.')
before={'vertices':sum(len(o.data.vertices) for o in objects),'polygons':sum(len(o.data.polygons) for o in objects)}
if settings['optimize_geometry']:
    for obj in objects:
        bm=bmesh.new();bm.from_mesh(obj.data)
        bmesh.ops.remove_doubles(bm,verts=list(bm.verts),dist=1e-6)
        bmesh.ops.recalc_face_normals(bm,faces=list(bm.faces))
        bm.to_mesh(obj.data);bm.free();obj.data.update()
for obj in bpy.context.scene.objects:obj.select_set(obj in objects)
bpy.ops.export_scene.gltf(filepath=settings['output'],export_format='GLB',use_selection=True,export_materials='EXPORT' if settings['include_materials'] else 'NONE')
after={'vertices':sum(len(o.data.vertices) for o in objects),'polygons':sum(len(o.data.polygons) for o in objects)}
Path(settings['details']).write_text(json.dumps({'version':bpy.app.version_string,'before':before,'after':after,'optimize_geometry':settings['optimize_geometry']},indent=2))
